<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('supervisor');
require_once __DIR__ . '/_helpers.php';
$user=current_user(); $supervisorId=(int)($user['id']??$user['user_id']??0);
if($supervisorId<=0){http_response_code(403);exit('Invalid Supervisor account.');}
$currentPage='support_interventions'; $pageTitle='Candidate Support & Interventions'; $flashes=render_flashes();
$error=''; $success='';
function sci_stmt(string $sql,string $types,array $params){return Database::prepare($sql,$types,$params);}
function sci_redirect(): void { header('Location: '.url('supervisor/support_interventions.php')); exit; }
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!sv_verify_csrf((string)($_POST['csrf_token']??''))){$error='Your session token is invalid. Refresh the page and try again.';}
  else {
    $action=(string)($_POST['action']??'');
    if($action==='create'){
      $candidateId=(int)($_POST['candidate_id']??0); $cohortId=(int)($_POST['cohort_id']??0);
      $category=trim((string)($_POST['concern_category']??'')); $severity=(string)($_POST['severity']??'medium');
      $summary=trim((string)($_POST['concern_summary']??'')); $support=trim((string)($_POST['support_provided']??''));
      $baseline=trim((string)($_POST['baseline_progress']??'')); $date=(string)($_POST['intervention_date']??date('Y-m-d'));
      $owner=trim((string)($_POST['assigned_to']??'')); $followAction=trim((string)($_POST['followup_action']??'')); $due=(string)($_POST['followup_due']??'');
      $categories=['attendance','academic_performance','workplace_performance','wellbeing','engagement','financial_or_logistical','other']; $severities=['low','medium','high','critical'];
      $validDate=DateTime::createFromFormat('Y-m-d',$date);
      $chk=sci_stmt("SELECT cp.user_id FROM cohort_participants cp JOIN cohorts c ON c.id=cp.cohort_id WHERE cp.user_id=? AND c.id=? AND c.supervisor_id=? LIMIT 1",'iii',[$candidateId,$cohortId,$supervisorId]);
      $allowed=(bool)$chk->get_result()->fetch_assoc();$chk->close();
      if(!$allowed||!in_array($category,$categories,true)||!in_array($severity,$severities,true)||$summary===''||$support===''||!$validDate){$error='Please complete the required fields and select a candidate from one of your assigned cohorts.';}
      elseif(($followAction!=='' && ($owner===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)))||($followAction===''&&($owner!==''||$due!==''))){$error='If you add a follow-up action, provide its owner and due date.';}
      else {
        $st=sci_stmt("INSERT INTO supervisor_candidate_interventions (candidate_id,cohort_id,supervisor_id,concern_category,severity,concern_summary,support_provided,baseline_progress,intervention_date) VALUES (?,?,?,?,?,?,?,?,?)",'iiissssss',[$candidateId,$cohortId,$supervisorId,$category,$severity,$summary,$support,$baseline?:null,$date]);
        $newId=(int)$st->insert_id;$st->close();
        if($followAction!==''){$fs=sci_stmt("INSERT INTO supervisor_intervention_followups (intervention_id,assigned_to,action_description,due_date,created_by) VALUES (?,?,?,?,?)",'isssi',[$newId,$owner,$followAction,$due,$supervisorId]);$fs->close();}
        sci_redirect();
      }
    } elseif($action==='followup_update'){
      $followId=(int)($_POST['followup_id']??0);$newStatus=(string)($_POST['followup_status']??'');$notes=trim((string)($_POST['completion_notes']??''));
      if(!in_array($newStatus,['open','in_progress','completed','cancelled'],true)){$error='Invalid follow-up status.';}
      else {
        $st=sci_stmt("UPDATE supervisor_intervention_followups f JOIN supervisor_candidate_interventions i ON i.id=f.intervention_id SET f.status=?,f.completion_notes=?,f.completed_at=CASE WHEN ?='completed' THEN COALESCE(f.completed_at,NOW()) ELSE NULL END WHERE f.id=? AND i.supervisor_id=?",'sssii',[$newStatus,$notes?:null,$newStatus,$followId,$supervisorId]);$st->close();sci_redirect();
      }
    } elseif($action==='review'){
      $id=(int)($_POST['intervention_id']??0);$status=(string)($_POST['intervention_status']??'monitoring');$effect=(string)($_POST['effectiveness']??'pending');$notes=trim((string)($_POST['outcome_notes']??''));
      if(!in_array($status,['open','monitoring','resolved','escalated'],true)||!in_array($effect,['pending','improved','no_change','declined'],true)){$error='Invalid review selection.';}
      else {$st=sci_stmt("UPDATE supervisor_candidate_interventions SET status=?,effectiveness=?,outcome_notes=?,reviewed_at=NOW() WHERE id=? AND supervisor_id=?",'sssii',[$status,$effect,$notes?:null,$id,$supervisorId]);$st->close();sci_redirect();}
    }
  }
}
// Candidate list is limited to cohorts assigned to the signed-in Supervisor.
$cs=sci_stmt("SELECT u.id candidate_id,u.first_name,u.last_name,c.id cohort_id,c.name cohort_name,p.name programme_name FROM cohort_participants cp JOIN cohorts c ON c.id=cp.cohort_id JOIN programmes p ON p.id=c.programme_id JOIN users u ON u.id=cp.user_id WHERE c.supervisor_id=? AND cp.status='active' ORDER BY c.name,u.first_name,u.last_name",'i',[$supervisorId]);$candidateOptions=$cs->get_result()->fetch_all(MYSQLI_ASSOC);$cs->close();
$filter=(string)($_GET['status']??'');$validFilters=['open','monitoring','resolved','escalated'];
$sql="SELECT i.*,u.first_name,u.last_name,c.name cohort_name,p.name programme_name,(SELECT COUNT(*) FROM supervisor_intervention_followups f WHERE f.intervention_id=i.id) followup_count,(SELECT COUNT(*) FROM supervisor_intervention_followups f WHERE f.intervention_id=i.id AND f.status NOT IN ('completed','cancelled')) pending_followups FROM supervisor_candidate_interventions i JOIN users u ON u.id=i.candidate_id JOIN cohorts c ON c.id=i.cohort_id JOIN programmes p ON p.id=c.programme_id WHERE i.supervisor_id=?";
$types='i';$params=[$supervisorId];if(in_array($filter,$validFilters,true)){$sql.=' AND i.status=?';$types.='s';$params[]=$filter;}$sql.=' ORDER BY FIELD(i.severity,\'critical\',\'high\',\'medium\',\'low\'), i.updated_at DESC LIMIT 200';
$st=sci_stmt($sql,$types,$params);$items=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();
$counts=['open'=>0,'monitoring'=>0,'resolved'=>0,'escalated'=>0];$q=sci_stmt("SELECT status,COUNT(*) total FROM supervisor_candidate_interventions WHERE supervisor_id=? GROUP BY status",'i',[$supervisorId]);$rr=$q->get_result();while($r=$rr->fetch_assoc())$counts[$r['status']]=(int)$r['total'];$q->close();
$followups=[];if($items){$ids=array_map(fn($x)=>(int)$x['id'],$items);$in=implode(',',array_fill(0,count($ids),'?'));$t=str_repeat('i',count($ids));$fq=sci_stmt("SELECT f.*,i.candidate_id,u.first_name,u.last_name FROM supervisor_intervention_followups f JOIN supervisor_candidate_interventions i ON i.id=f.intervention_id JOIN users u ON u.id=i.candidate_id WHERE i.supervisor_id=? AND i.id IN ($in) ORDER BY f.due_date ASC",'i'.$t,array_merge([$supervisorId],$ids));$followups=$fq->get_result()->fetch_all(MYSQLI_ASSOC);$fq->close();}
require __DIR__.'/_layout_start.php';
?>
