mplate-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.sci-grid,.sci-form{grid-template-columns:1fr}.sci-item-head{display:block}}
html[data-theme="dark"] .sci-stat,html[data-theme="dark"] .sci-panel,html[data-theme="dark"] .sci-item,body.dark-mode .sci-stat,body.dark-mode .sci-panel,body.dark-mode .sci-item{background:#182235;color:#e5eaf3;border-color:#344258}html[data-theme="dark"] .sci-field input,html[data-theme="dark"] .sci-field select,html[data-theme="dark"] .sci-field textarea,body.dark-mode .sci-field input,body.dark-mode .sci-field select,body.dark-mode .sci-field textarea{background:#101a2b;color:#e5eaf3;border-color:#3b4b63}
</style>
