<?php if($error): ?><div class="sv-security" style="margin:14px 0"><i class="fas fa-circle-exclamation"></i><div><?=e($error)?></div></div><?php endif; ?>
<div class="sci-grid"><div class="sci-stat"><span>Open interventions</span><strong><?= (int)$counts['open'] ?></strong></div><div class="sci-stat"><span>Being monitored</span><strong><?= (int)$counts['monitoring'] ?></strong></div><div class="sci-stat"><span>Resolved</span><strong><?= (int)$counts['resolved'] ?></strong></div><div class="sci-stat"><span>Escalated</span><strong><?= (int)$counts['escalated'] ?></strong></div></div>
