<div class="sci-field"><label>Concern category *</label><select name="concern_category" required><option value="">Select category</option><?php foreach(['attendance'=>'Attendance','academic_performance'=>'Academic performance','workplace_performance'=>'Workplace performance','wellbeing'=>'Wellbeing','engagement'=>'Engagement','financial_or_logistical'=>'Financial / logistical','other'=>'Other'] as $k=>$v): ?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach; ?></select></div>
<div class="sci-field"><label>Severity *</label><select name="severity"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option><option value="critical">Critical</option></select></div>
