<div class="sci-list" style="margin-top:14px"><?php if(!$items): ?><div class="sci-empty">No support interventions recorded yet.</div><?php endif; ?><?php foreach($items as $it): ?><article class="sci-item"><div class="sci-item-head"><div><strong><?=e($it['first_name'].' '.$it['last_name'])?></strong><div class="sci-muted"><?=e($it['programme_name'].' · '.$it['cohort_name'])?> · <?=e(sv_date($it['intervention_date']))?></div></div><div class="sci-tags"><span class="sci-tag <?=e($it['severity'])?>"><?=e(ucfirst($it['severity']))?> priority</span><span class="sci-tag"><?=e(ucwords(str_replace('_',' ',$it['status'])))?></span><span class="sci-tag"><?=e(ucwords(str_replace('_',' ',$it['effectiveness'])))?></span></div></div><p><strong>Concern:</strong> <?=e($it['concern_summary'])?></p><p><strong>Support provided:</strong> <?=nl2br(e($it['support_provided']))?></p><?php if($it['baseline_progress']): ?><p class="sci-muted"><strong>Baseline:</strong> <?=e($it['baseline_progress'])?></p><?php endif; ?>
<form method="post" class="sci-review"><input type="hidden" name="csrf_token" value="<?=e(sv_csrf_token())?>"><input type="hidden" name="action" value="review"><input type="hidden" name="intervention_id" value="<?=(int)$it['id']?>"><label>Status <select name="intervention_status"><?php foreach(['open','monitoring','resolved','escalated'] as $s): ?><option value="<?=$s?>" <?=$it['status']===$s?'selected':''?>><?=e(ucwords($s))?></option><?php endforeach; ?></select></label><label>Effectiveness <select name="effectiveness"><?php foreach(['pending','improved','no_change','declined'] as $s): ?><option value="<?=$s?>" <?=$it['effectiveness']===$s?'selected':''?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach; ?></select></label><label style="flex:1;min-width:180px">Outcome notes <input name="outcome_notes" value="<?=e($it['outcome_notes']??'')?>" placeholder="Progress observed since support"></label><button class="sci-btn" type="submit">Save review</button></form>
<?php foreach($followups as $f): if((int)$f['intervention_id']!==(int)$it['id'])continue; ?><div class="sci-follow"><strong>Follow-up:</strong> <?=e($f['action_description'])?><div class="sci-muted">Owner: <?=e($f['assigned_to'])?> · Due: <?=e(sv_date($f['due_date']))?> · Status: <?=e(ucwords(str_replace('_',' ',$f['status'])))?></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(sv_csrf_token())?>"><input type="hidden" name="action" value="followup_update"><input type="hidden" name="followup_id" value="<?=(int)$f['id']?>"><select name="followup_status"><?php foreach(['open','in_progress','completed','cancelled'] as $s): ?><option value="<?=$s?>" <?=$f['status']===$s?'selected':''?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach; ?></select><input name="completion_notes" value="<?=e($f['completion_notes']??'')?>" placeholder="Update / completion notes"><button class="sci-btn" type="submit">Update follow-up</button></form></div><?php endforeach; ?></article><?php endforeach; ?></div></section>
